package instructive.parse.x86;

import instructive.parse.InstructionKind;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.regex.Pattern;

/**
 * The SSE, AVX and AVX-512 instructions, loaded from {@code opcodes.txt}. That file is
 * generated by {@code parse/tools/x86/opcodes.py}, which probes LLVM's disassembler with
 * every encoding and records how it prints each one as an operand template.
 *
 * <p>Each line is keyed by encoding ({@code L} legacy, {@code V} VEX, {@code E} EVEX),
 * opcode map, mandatory prefix (0 none, 1 66, 2 F3, 3 F2), opcode, operand form ({@code r}
 * register, {@code m} memory, with {@code b} when EVEX.b is set), and the sets of W, vector
 * length and ModRM.reg values it covers. EVEX lines also say which masking combinations
 * are accepted ({@code 0} unmasked, {@code k} merging, {@code z} zeroing, {@code Z} zeroing
 * without a mask) and {@code V} when vvvv must be unused (all ones).
 *
 * <p>Operands name the field they come from: {@code R} ModRM.reg, {@code M} ModRM.rm as
 * a register, {@code V} vvvv, {@code S} the register in the upper half of an immediate,
 * {@code A} the memory operand, {@code I}/{@code J} the first/second immediate byte,
 * {@code I4} the low four bits of a byte whose upper half is an {@code S} register,
 * {@code RC}/{@code SAE} embedded rounding, {@code KM} the mask as an operand, and
 * {@code =name} a fixed register. Each carries one detail per vector length: the register
 * class ({@code x y z} vector, {@code k} mask, {@code m} MMX, {@code t} tile, {@code b w d q}
 * general purpose) or the memory size ({@code b w d q x y z t}, {@code -} for none),
 * followed for a VSIB address by the index class in capitals, for a broadcast by
 * {@code {1toN}}, and for an EVEX memory operand by {@code @N}, the scale of an 8-bit
 * displacement. Immediates are {@code u} (printed unsigned) or {@code s} (signed).
 */
final class OpcodeTable {
    static final int LEGACY = 0, VEX = 1, EVEX = 2;

    /** One operand of a template; {@code details} is indexed by vector length. */
    record Operand(String source, String[] details) {}

    static final class Entry {
        final int encoding;
        final boolean memory, broadcast;
        final int wSet, lSet, regSet;
        final boolean unmasked, merging, zeroing, zeroingUnmasked, noVvvv;
        final String mnemonic;
        final boolean noModrm;
        final Operand[] operands;
        final String[] immediateNames;
        final int immediateBytes;
        final InstructionKind kind;

        Entry(String line) {
            String[] columns = line.split("\t", -1);
            String[] key = columns[0].split(" ");
            encoding = switch (key[0]) {
                case "L" -> LEGACY;
                case "V" -> VEX;
                default -> EVEX;
            };
            memory = key[4].startsWith("m");
            broadcast = key[4].endsWith("b");
            wSet = digits(key[5].substring(1));
            lSet = digits(key[6].substring(1));
            regSet = digits(key[7].substring(1));
            String flags = key.length > 8 ? key[8] : "";
            unmasked = encoding != EVEX || flags.contains("0");
            merging = flags.contains("k");
            zeroing = flags.contains("z");
            zeroingUnmasked = flags.contains("Z");
            noVvvv = flags.contains("V");
            String name = columns[1];
            noModrm = name.endsWith("|nomodrm");
            mnemonic = noModrm ? name.substring(0, name.length() - "|nomodrm".length()) : name;
            List<Operand> list = new ArrayList<>();
            int bytes = 0;
            boolean is4 = false;
            if (!columns[2].isEmpty()) {
                for (String text : columns[2].split(" ")) {
                    int colon = text.indexOf(':');
                    String source = colon < 0 ? text : text.substring(0, colon);
                    String[] details = new String[4];
                    if (colon >= 0) {
                        String[] perLength = text.substring(colon + 1).split("\\|", -1);
                        int i = 0;
                        for (int l = 0; l < 4; l++) {
                            if ((lSet & 1 << l) != 0) {
                                details[l] = perLength[i++];
                            }
                        }
                    }
                    list.add(new Operand(source, details));
                    if (source.equals("I") || source.equals("J")) {
                        bytes++;
                    } else if (source.equals("S")) {
                        is4 = true;
                    }
                }
            }
            operands = list.toArray(Operand[]::new);
            // The is4 register shares the first immediate byte.
            immediateBytes = Math.max(bytes, is4 ? 1 : 0);
            if (columns.length > 3 && !columns[3].isEmpty()) {
                immediateNames = new String[256];
                for (String pair : columns[3].split(",")) {
                    int eq = pair.indexOf('=');
                    immediateNames[Integer.parseInt(pair.substring(0, eq), 16)] = pair.substring(eq + 1);
                }
            } else {
                immediateNames = null;
            }
            kind = classify(mnemonic, operands);
        }

        private static int digits(String s) {
            int set = 0;
            for (int i = 0; i < s.length(); i++) {
                set |= 1 << (s.charAt(i) - '0');
            }
            return set;
        }
    }

    private static final Pattern MOVE = Pattern.compile(
            "v?p?(mov|broadcast|gather|lddqu|expand|kmov|maskmov|pmovzx|pmovsx|insert|movnt|pinsr).*");
    private static final Pattern SCALAR_FLOATING_POINT = Pattern.compile(
            "v?(u?comis[sdh]|cvt\\w*(ss|sd|sh|si|si2s[sdh])|cvtu?si2s[sdh]|(?!p|mov|broadcast|blend|perm|unpck|insert|extract|gather|scatter|compress|expand|mask)\\w*(ss|sd|sh))");

    /** Coarse kind of a table instruction, for analysing hot code. */
    private static InstructionKind classify(String mnemonic, Operand[] operands) {
        String name = mnemonic.startsWith("{") ? mnemonic.substring(mnemonic.indexOf(' ') + 1) : mnemonic;
        if (name.startsWith("prefetch") || name.contains("gatherpf") || name.contains("scatterpf")) {
            return InstructionKind.PREFETCH;
        }
        boolean vector = false;
        int memoryAt = -1;
        for (int i = 0; i < operands.length; i++) {
            Operand operand = operands[i];
            if (operand.source().equals("A")) {
                memoryAt = i;
            } else if (operand.source().length() == 1 && "RMVS".contains(operand.source())) {
                for (String detail : operand.details()) {
                    if (detail != null && !"bwdq".contains(detail)) {
                        vector = true;
                    }
                }
            } else if (operand.source().startsWith("=") && !operand.source().matches("=[re]?[a-d]x|=[a-d]l")) {
                vector = true;
            }
        }
        if (name.equals("vzeroupper") || name.equals("vzeroall") || name.equals("emms")) {
            return InstructionKind.SIMD;
        }
        if (!vector) {
            if (name.equals("movbe") || name.startsWith("movdir")) {
                return memoryAt == 0 ? InstructionKind.STORE : InstructionKind.LOAD;
            }
            return memoryAt == 0 && name.startsWith("v") ? InstructionKind.STORE
                    : name.startsWith("vmread") || name.startsWith("vmwrite") ? InstructionKind.SYSTEM : InstructionKind.ALU;
        }
        if (memoryAt == 0) {
            return InstructionKind.STORE;
        }
        if (memoryAt > 0 && MOVE.matcher(name).matches()) {
            return InstructionKind.LOAD;
        }
        if (SCALAR_FLOATING_POINT.matcher(name).matches()) {
            return InstructionKind.FLOATING_POINT;
        }
        return InstructionKind.SIMD;
    }

    private static final class Holder {
        static final OpcodeTable INSTANCE = load();
    }

    private final Map<Integer, List<Entry>> entries;

    private OpcodeTable(Map<Integer, List<Entry>> entries) {
        this.entries = entries;
    }

    static OpcodeTable instance() {
        return Holder.INSTANCE;
    }

    /** The entries for an opcode, or an empty list. */
    List<Entry> candidates(int encoding, int map, int pp, int opcode) {
        return entries.getOrDefault(key(encoding, map, pp, opcode), List.of());
    }

    private static int key(int encoding, int map, int pp, int opcode) {
        return encoding << 16 | map << 10 | pp << 8 | opcode;
    }

    private static OpcodeTable load() {
        Map<Integer, List<Entry>> entries = new HashMap<>();
        try (var in = Objects.requireNonNull(OpcodeTable.class.getResourceAsStream("opcodes.txt"), "opcodes.txt");
                var reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8))) {
            for (String line; (line = reader.readLine()) != null; ) {
                if (line.isEmpty() || line.startsWith("#")) {
                    continue;
                }
                String[] key = line.substring(0, line.indexOf('\t')).split(" ");
                Entry entry = new Entry(line);
                int k = key(entry.encoding, Integer.parseInt(key[1]), Integer.parseInt(key[2]), Integer.parseInt(key[3], 16));
                entries.computeIfAbsent(k, x -> new ArrayList<>()).add(entry);
            }
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
        return new OpcodeTable(entries);
    }
}
